std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto v = rt.vertices_begin(); v != rt.vertices_end(); ++v) {
    // Position is the vertex point in the Regular Triangulation
    Point pos = v->point();

    // Velocity is computed based on the cell/vertex properties
    // In the context of Adhesion, we use the velocity function provided in the class
    Vector vel = velocity(v);

    // Mass is typically associated with the weight of the vertex in RT
    double mass = v->weight();

    // Classification based on the number of edges connected to the vertex
    // that are larger than the given threshold
    int edge_count = 0;
    for (auto e = rt.halfedge(v); e != nullptr; e = rt.halfedge(v)) {
        // We count edges that are NOT "small" (i.e., they exceed the threshold)
        // Based on Context 4, is_small_edge checks squared_length < threshold
        if (!is_small_edge(rt, e, threshold)) {
            edge_count++;
        }
        // Note: In CGAL RT, we must iterate carefully. 
        // Since we need the total count of unique edges, we divide by 2 
        // or use a specific iterator. However, the provided type_from_edge_count 
        // logic suggests a direct mapping from the count of significant connections.
    }

    // Correcting edge count: CGAL halfedges are directed. 
    // For a vertex, the number of incident edges is the number of outgoing halfedges.
    int incident_edges = 0;
    auto he = rt.halfedge(v);
    if (he != nullptr) {
        do {
            if (!is_small_edge(rt, he, threshold)) {
                incident_edges++;
            }
            he = rt.next_around_vertex(he);
        } while (he != rt.halfedge(v));
    }

    NodeType type = type_from_edge_count(incident_edges);

    nodes.push_back({pos, vel, mass, type});
}

return nodes;

